package main

import (
	"fmt"
	"strings"
)

func renderSearchDart(input searchGenerationInput) []byte {
	var b strings.Builder
	b.WriteString("// Code generated by codegen_graphql_app_search_client. DO NOT EDIT.\n")
	fmt.Fprintf(&b, "// ContractGraph SHA256: %s\n", input.graphDigest)
	fmt.Fprintf(&b, "// Persisted registry SHA256: %s\n\n", input.registryDigest)
	b.WriteString("import 'package:quwoquan_cloud_contracts/quwoquan_cloud_contracts.dart';\n")
	b.WriteString("import 'package:quwoquan_cloud_contracts/generated/gateway_contracts.dart';\n\n")
	b.WriteString("final class SearchPagePersistedGraphQLDescriptor {\n")
	b.WriteString("  const SearchPagePersistedGraphQLDescriptor({required this.operationName, required this.canonicalOperationId, required this.sha256Hash, required this.schemaDigest, required this.costPlanDigest, required this.sloRef, required this.responseKey, required this.selectedFields, required this.depth, required this.topLevelFields, required this.worstCaseComplexity, required this.variablesMaxBytes, required this.maxOwnerCalls, required this.maxBatchKeys, required this.maxResponseBytes});\n")
	b.WriteString("  final String operationName;\n  final String canonicalOperationId;\n  final String sha256Hash;\n  final String schemaDigest;\n  final String costPlanDigest;\n  final String sloRef;\n  final String responseKey;\n  final List<String> selectedFields;\n  final int depth;\n  final int topLevelFields;\n  final int worstCaseComplexity;\n  final int variablesMaxBytes;\n  final int maxOwnerCalls;\n  final int maxBatchKeys;\n  final int maxResponseBytes;\n}\n\n")
	b.WriteString("const SearchPagePersistedGraphQLDescriptor _searchPageDescriptor = SearchPagePersistedGraphQLDescriptor(\n")
	fmt.Fprintf(&b, "  operationName: %s, canonicalOperationId: %s, sha256Hash: %s,\n", dartString(input.entry.OperationName), dartString(input.entry.CanonicalOperationID), dartString(input.entry.SHA256Hash))
	fmt.Fprintf(&b, "  schemaDigest: %s, costPlanDigest: %s, sloRef: %s, responseKey: %s,\n", dartString(input.schemaDigest), dartString(input.entry.CostPlanDigest), dartString(input.entry.Cost.SLORef), dartString(input.responseKey))
	renderStringList(&b, "selectedFields", input.selectedFields, 2)
	fmt.Fprintf(&b, "  depth: %d, topLevelFields: %d, worstCaseComplexity: %d, variablesMaxBytes: %d,\n", input.entry.Cost.Depth, input.entry.Cost.TopLevelFields, input.entry.Cost.Complexity, input.entry.Cost.VariablesMaxBytes)
	fmt.Fprintf(&b, "  maxOwnerCalls: %d, maxBatchKeys: %d, maxResponseBytes: %d,\n", input.entry.Cost.MaxOwnerCalls, input.entry.Cost.MaxBatchKeys, input.entry.Cost.MaxResponseBytes)
	b.WriteString(");\n\n")
	b.WriteString("final class GeneratedSearchPageGraphQLClient {\n")
	b.WriteString("  const GeneratedSearchPageGraphQLClient(this._executor);\n  final CloudOperationExecutor _executor;\n\n")
	fmt.Fprintf(&b, "  Future<%s> searchPage(%s request, {required CloudOperationInvocationContext context}) {\n", input.appOperation.ClientContract.ResponseType, input.inputType)
	fmt.Fprintf(&b, "    return _executor.send<%s>(_persistedGraphQLTransportOperation, context: context, responseDecoder: _decodeSearchPageResponse, requestEncoder: () => CloudOperationRequestPayload(body: <String, Object?>{\n", input.appOperation.ClientContract.ResponseType)
	b.WriteString("      'operationName': _searchPageDescriptor.operationName,\n")
	b.WriteString("      'variables': <String, Object?>{'input': request.toWire()},\n")
	b.WriteString("      'extensions': <String, Object?>{'persistedQuery': <String, Object?>{'version': 1, 'sha256Hash': _searchPageDescriptor.sha256Hash}},\n")
	b.WriteString("    }));\n  }\n}\n\n")
	fmt.Fprintf(&b, "%s _decodeSearchPageResponse(Object? response) {\n", input.appOperation.ClientContract.ResponseType)
	b.WriteString("  final envelope = _requiredSearchGraphQLObject(response, 'GraphQLReadResponse');\n")
	b.WriteString("  if (envelope.length != 1 || !envelope.containsKey('data')) throw const FormatException('GraphQLReadResponse must contain only data');\n")
	b.WriteString("  final data = _requiredSearchGraphQLObject(envelope['data'], 'GraphQLReadResponse.data');\n")
	b.WriteString("  if (data.length != 1 || !data.containsKey(_searchPageDescriptor.responseKey)) throw const FormatException('GraphQLReadResponse.data differs from signed SearchPage root');\n")
	b.WriteString("  final root = _requiredSearchGraphQLObject(data[_searchPageDescriptor.responseKey], _searchPageDescriptor.responseKey);\n")
	b.WriteString("  final actual = root.keys.toSet();\n  final expected = _searchPageDescriptor.selectedFields.toSet();\n")
	b.WriteString("  if (actual.length != expected.length || !actual.containsAll(expected)) throw const FormatException('SearchPage fields differ from signed projection');\n")
	fmt.Fprintf(&b, "  return %s(root);\n}\n\n", input.appOperation.ClientContract.ResponseDecoder)
	b.WriteString("Map<String, Object?> _requiredSearchGraphQLObject(Object? value, String path) {\n")
	b.WriteString("  if (value is! Map) throw FormatException('$path must be an object');\n  final result = <String, Object?>{};\n  for (final entry in value.entries) {\n    if (entry.key is! String) throw FormatException('$path contains a non-string key');\n    result[entry.key as String] = entry.value;\n  }\n  return result;\n}\n\n")
	renderGatewayContract(&b, input.gateway, input.appOperation)
	return []byte(b.String())
}
